-- DDL: opisujemo strukturu
CREATE TABLE student (
  bri   INT PRIMARY KEY,
  ime   VARCHAR(50),
  bpi   INT
);

-- DML: unosimo i menjamo podatke
INSERT INTO student (bri, ime, bpi) VALUES (13, 'Nikola', 10);
UPDATE student SET bpi = 12 WHERE bri = 13;

-- QL: postavljamo upit
SELECT ime, bpi FROM student WHERE bpi >= 10;

CREATE VIEW student_fakultet AS
SELECT s.bri, s.ime, s.prz, s.bpi, f.naf
FROM student s
JOIN fakultet f ON f.id = s.fakultet_id;

-- korisnik pita pogled kao da je običan tabela:
SELECT * FROM student_fakultet WHERE bpi > 8;
